    cps = {r['position_id']: r for r in csv.DictReader(f)}

with open(f'{base_dir}/site/crane_chart.csv') as f:
    chart_rows = [(float(r['radius_ft']), float(r['rated_capacity_lb'])) for r in csv.DictReader(f)]
chart_rows.sort()

def interpolate_crane_capacity(r):
    if r <= chart_rows[0][0]:
        return chart_rows[0][1]
    if r >= chart_rows[-1][0]:
        return chart_rows[-1][1]
    for i in range(len(chart_rows)-1):
        r1, c1 = chart_rows[i]
        r2, c2 = chart_rows[i+1]
        if r1 <= r <= r2:
            return round(c1 + (c2 - c1) * (r - r1) / (r2 - r1), 2)
    return 0.0

